function playTone(kind: "water" | "harvest" | "pet" | "plant" | "day" | "click" | "purr" | "bee" | "leaf" | "windchime", enabled: boolean, volume = .55) { if (!enabled || typeof window === "undefined") return; try { const Ctx = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext; if (!Ctx) return; const ctx = new Ctx(); const now = ctx.currentTime; if (kind === "leaf") { const buffer = ctx.createBuffer(1, ctx.sampleRate * .28, ctx.sampleRate); const data = buffer.getChannelData(0); for (let i = 0; i < data.length; i += 1) data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / data.length, 2); const source = ctx.createBufferSource(); const filter = ctx.createBiquadFilter(); const gain = ctx.createGain(); filter.type = "bandpass"; filter.frequency.value = 1800; filter.Q.value = .7; gain.gain.setValueAtTime(.0001, now); gain.gain.exponentialRampToValueAtTime(.08 * volume, now + .025); gain.gain.exponentialRampToValueAtTime(.0001, now + .28); source.buffer = buffer; source.connect(filter).connect(gain).connect(ctx.destination); source.start(now); source.stop(now + .3); return; } const notes = kind === "windchime" ? [1318, 1760, 2217] : ({ water: [520, 720], harvest: [440, 660, 880], pet: [330, 392, 494], plant: [260, 330], day: [392, 494, 659], click: [180, 240], purr: [92, 110, 130], bee: [244, 320, 410] }[kind]); notes.forEach((note, index) => { const osc = ctx.createOscillator(); const gain = ctx.createGain(); osc.type = kind === "water" || kind === "purr" ? "sine" : "triangle"; osc.frequency.setValueAtTime(note, now + index * .07); gain.gain.setValueAtTime(.0001, now + index * .07); gain.gain.exponentialRampToValueAtTime((kind === "windchime" ? .045 : .055) * volume, now + index * .07 + .018); gain.gain.exponentialRampToValueAtTime(.0001, now + index * .07 + (kind === "windchime" ? 1.15 : kind === "purr" ? .7 : .42)); osc.connect(gain).connect(ctx.destination); osc.start(now + index * .07); osc.stop(now + index * .07 + (kind === "windchime" ? 1.2 : .5)); }); } catch { /* enhancement only */ } }
function playMusicBoxMelody(notes: number[], enabled: boolean, volume = .45) { if (!enabled || typeof window === "undefined") return; try { const Ctx = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext; if (!Ctx) return; const ctx = new Ctx(); const now = ctx.currentTime; notes.forEach((note, index) => { const start = now + index * .2; const osc = ctx.createOscillator(); const gain = ctx.createGain(); osc.type = "sine"; osc.frequency.setValueAtTime(note, start); gain.gain.setValueAtTime(.0001, start); gain.gain.exponentialRampToValueAtTime(.07 * volume, start + .025); gain.gain.exponentialRampToValueAtTime(.0001, start + .62); osc.connect(gain).connect(ctx.destination); osc.start(start); osc.stop(start + .68); }); } catch { /* enhancement only */ } }

